import {SAVE_KEY,TAGS,PEOPLE,DESTINATIONS,TAG_LABELS,MASKS,flipMask,project,cells,initial,act,restore} from './core.js?v=203';
const app=document.querySelector('#game');
const names={haru:'하루',maki:'마키',yui:'유이',ken:'켄'},places={workshop:'새 작업실',gallery:'전시',post:'우편',locker:'보관함'};
const notes=[
 {name:'마키',color:'#d4c786',angle:'-5deg',front:'삼각표 인화가 끝나자마자\n원형표 인화를 하셨죠.\n\n마지막 날에도\n커피는 따뜻했어요.',back:'전시에 쓸 인화는\n첫 번째 작업이 아니었어요.\n\n다음 가게의 벽에도\n걸어 주실 거죠?'},
 {name:'켄',color:'#b7c5ab',angle:'3deg',front:'원형표와 십자표 작업\n사이에는 딱 한 작업이\n있었어요.\n\n기록이 지워지기 전에\n확인 부탁드려요.',back:'제 사진은\n보관함에 넣어 주세요.\n\n새 가게가 열리면\n제가 직접 찾으러 갈게요.'},
 {name:'유이',color:'#d8b59b',angle:'-2deg',front:'원형표 작업이\n십자표보다 먼저 끝났죠.\n\n기다리는 동안 창밖의 비를\n한참 보고 있었어요.',back:'제 인화 바로 다음이\n켄의 인화였어요.\n\n저는 먼저 떠나지만\n다시 들를게요.'}
];
const blankDraft=()=>({people:[null,null,null,null],destinations:[null,null,null,null]});
let log=[],state=initial(),ui={started:false,seen:{},draft:blankDraft(),sound:false},storage=true;
try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY));if(raw?.schema===2){log=Array.isArray(raw.events)&&raw.events.length<=5000?raw.events:[];state=restore(raw);const saved=raw.ui||{};ui={...ui,started:saved.started===true,seen:saved.seen&&typeof saved.seen==='object'?saved.seen:{},sound:saved.sound===true,draft:validDraft(saved.draft)?saved.draft:blankDraft()};}}catch{}
let view=null,selectedSlot=null,selectedToken=null,lastFocus=null,paperKind=null,noteSide=0,noteIndex=0,hintLevel=0,hintPhase='',statusTimer=null,pointer=null,sampleTurned=false,showLight=false,audio=null,ready=false;
app.innerHTML=`<section class="scene" aria-label="雨の夜の写真館"><header class="topbar"><button class="round" id="menu" aria-label="メニューを開く">≡</button><div class="title">마지막 현상실<small>미나미 사진관 · 마지막 밤</small></div><button class="round" id="hint" aria-label="힌트">?</button></header><div id="room-objects"></div><p class="scene-status" id="scene-status" role="status" aria-live="polite"></p><nav class="bottom-dock" aria-label="가지고 있는 기록"><button class="dock-button" id="request"><span aria-hidden="true">✉</span>의뢰 봉투</button><button class="dock-button" id="notebook"><span aria-hidden="true">▤</span>관찰 수첩</button></nav></section><section id="view" class="view" hidden aria-label="사물 가까이 보기"><header class="view-head"><button class="round small" id="view-back" aria-label="방으로 돌아가기">‹</button><h2 id="view-title"></h2><div style="display:flex;gap:5px"><button class="round small" id="view-notes" aria-label="관찰 수첩 열기">▤</button><button class="round small" id="view-help" aria-label="퍼즐 힌트">?</button></div></header><div class="workspace" id="workspace"></div><footer class="view-foot" id="view-foot"></footer></section><section class="modal" id="modal" hidden role="dialog" aria-modal="true" aria-label="기록 살펴보기"><article class="paper" id="paper"></article></section><div class="loading" id="loading">작업실에 불을 켜는 중…</div>`;
const $=id=>document.getElementById(id);
$('menu').setAttribute('aria-label','메뉴 열기');document.querySelector('.scene').setAttribute('aria-label','비 내리는 밤의 사진관');
function validDraft(d){if(!d||typeof d!=='object')return false;return[['people',PEOPLE],['destinations',DESTINATIONS]].every(([k,domain])=>Array.isArray(d[k])&&d[k].length===4&&d[k].every(x=>x===null||domain.includes(x))&&new Set(d[k].filter(Boolean)).size===d[k].filter(Boolean).length);}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({schema:2,events:log,ui}));}catch{storage=false;say('이 브라우저에서는 저장이 제한돼요. 이 창을 닫지 않으면 이어갈 수 있어요.');}}
function tick(kind='touch'){if(!ui.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=kind==='open'?'sine':'triangle';o.frequency.setValueAtTime(kind==='open'?240:kind==='fail'?90:460,t);o.frequency.exponentialRampToValueAtTime(kind==='open'?470:120,t+.12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.045,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.15);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.16);}catch{}}
function say(text,ms=6500){clearTimeout(statusTimer);$('scene-status').textContent=text;if(ms)statusTimer=setTimeout(()=>$('scene-status').textContent='',ms);}
function message(text){const node=$('view-message');if(node)node.textContent=text;else say(text);}
function action(e){const r=act(state,e);if(!r.ok){tick('fail');message({'sequence-mismatch':'캐리어가 끝까지 들어가지 않아요.\n세 사람은 작업 순서를 어떻게 기억하고 있었을까요?','keyed-carrier':'△판은 비대칭 핀에 고정돼 있어요. 다른 세 판은 뒤집을 수 있어요.','ledger-mismatch':'복원한 배달표와 기록 사이에 모순이 있어요.\n사람과 행선지를 함께 비교해 보세요.','dispatch-ledger-missing':'보관함 안에 배달 장부가 남아 있어요.','episode-complete':'네 장의 사진을 모두 돌려보냈어요.'}[r.reason]||'아직 이 장치를 사용할 수 없어요.');return r;}state=r.state;log.push(e);save();tick(e.type==='feed'||e.type==='deliver'?'open':'touch');renderRoom();return r;}
function miniNotes(){return notes.map((n,i)=>`<button class="sticky-mini" data-note="${i}" style="--note:${n.color};--angle:${n.angle}" aria-label="${n.name}의 포스트잇 읽기">${['커피는<br>따뜻했어요','기록을<br>확인해 주세요','또다시<br>들를게요'][i]}<small>— ${n.name}</small></button>`).join('');}
function renderRoom(){$('request').hidden=!ui.started;$('notebook').hidden=!ui.started;const obj=$('room-objects');if(!ui.started){obj.innerHTML='<button class="room-object envelope invite" data-act="request" aria-label="작업대의 봉투 열기"><i class="seal">M</i><b>마지막 네 장</b><small>미나미 사진관 · 하루</small></button>';return;}let body=`<div class="notes-wall">${miniNotes()}</div>`;
 if(state.phase==='table')body+=`<button class="room-object mini-machine" data-act="order" aria-label="작업대의 필름 캐리어 살펴보기">${state.order.map(x=>`<span class="mini-plate">${TAG_LABELS[x]}</span>`).join('')}<small class="label">마지막 인화 작업</small></button>`;
 else body+=`<button class="room-object mini-machine" data-act="projector" aria-label="빛 투사기 살펴보기"><span class="machine-light">${state.archive?'한 점의 빛 · '+state.archive:'빛이 지나간 자리'}</span><small class="label">보관 기록 투사기</small></button>`;
 if(state.archive)body+=`<button class="room-object drawer-object" data-act="archive" aria-label="열린 C3 보관함 살펴보기">C3</button>`;
 if(state.complete)body+=`<button class="room-object envelope" data-act="ending" aria-label="완성한 네 장의 사진 보기"><i class="seal">✓</i><b>도착한 사진들</b><small>새 작업실에서 온 답장</small></button>`;
 obj.innerHTML=body;$('request').hidden=!ui.started;
}
function showPaper(kind,html,{color=null,closable=true}={}){document.querySelector('.scene').inert=true;$('view').inert=true;lastFocus=document.activeElement;paperKind=kind;$('paper').className='paper'+(color?' sticky':'')+(kind==='ending'?' ending':'');$('paper').style.setProperty('--note',color||'#e8ddbd');$('paper').innerHTML=(closable?'<button class="close" data-act="close-paper" aria-label="내려놓기">×</button>':'')+html;$('modal').hidden=false;$('paper').querySelector('button,a')?.focus();}
function closePaper(){paperKind=null;$('modal').hidden=true;document.querySelector('.scene').inert=!!view;$('view').inert=false;lastFocus?.isConnected&&lastFocus.focus?.();}
function request(){showPaper('request',`<p class="overline">MINAMI PHOTO STUDIO · 最後の依頼</p><h2>단 한 장도<br>남겨두지 말아 주세요.</h2><p>내일 이 사진관이 철거돼요.\n그런데 마지막 네 장의\n주인과 행선지가 지워졌어요.</p><p>아버지가 남긴 작업 기록을 찾으면\n사진을 돌려보낼 수 있을 거예요.</p><p class="signature">— 하루</p><button class="action" data-act="begin">작업대 살펴보기</button><p class="small">서두르지 않아도 돼요.\n사물을 눌러 살펴보고, 기록을 함께 읽어 주세요.</p>`,{closable:ui.started});}
function openNote(i,side=0){noteIndex=i;noteSide=side;const n=notes[i];ui.seen[`${i}:${side}`]=true;save();showPaper('note',`<span class="note-side">${side?'종이 뒷면':'접힌 모서리가 있는 종이'}</span><p>${side?n.back:n.front}</p><p class="signature">— ${n.name}</p><button class="subtle" data-act="flip-note">↻ ${side?'앞면':'뒷면'} 보기</button><button class="subtle" data-act="close-paper">제자리에 붙여두기</button>`,{color:n.color});}
function notebook(){let body='<p class="overline">OBSERVATIONS</p><h2>내가 읽은 기록</h2>';
 for(let i=0;i<3;i++){const n=notes[i],seen0=ui.seen[`${i}:0`],seen1=ui.seen[`${i}:1`];if(!seen0&&!seen1)continue;body+=`<div class="notebook-entry"><button data-note="${i}">${n.name}의 포스트잇 ↗</button>${seen0?`<p>${n.front.replaceAll('\n','<br>')}</p>`:''}${seen1?`<p>뒷면 · ${n.back.replaceAll('\n','<br>')}</p>`:''}</div>`;}
 if(state.experiments.length)body+=`<div class="notebook-entry"><p>빛 실험 기록</p>${state.experiments.map((e,i)=>`<p>${i+1}. ${e.faces.map(b=>b?'뒤':'앞').join(' · ')} → ${e.lit.length?e.lit.join(', '):'빛 없음'}</p>`).join('')}</div>`;
 if(ui.seen.ledger)body+='<div class="notebook-entry"><p>C3 장부 · 세 번째 작업: 우편 발송.<br>새 주소표 · 하루의 사진: 새 작업실.</p></div>';
 if(!Object.keys(ui.seen).length&&!state.experiments.length)body+='<p>아직 읽은 기록이 없어요.\n벽에 붙은 작은 종이부터 살펴볼까요?</p>';
 body+='<button class="subtle" data-act="close-paper">수첩 덮기</button>';showPaper('notebook',body);}
function openView(type){document.querySelector('.scene').inert=true;view=type;selectedSlot=null;selectedToken=null;$('view').hidden=false;renderView();$('view-back').focus();}
function closeView(){document.querySelector('.scene').inert=false;view=null;$('view').hidden=true;renderRoom();}
function foot(button,label){$('view-foot').innerHTML=`${button?`<button class="action" data-act="${button}">${label}</button>`:''}<p class="view-message" id="view-message" role="status" aria-live="polite"></p>`;}
function deskNotes(){return`<div class="desk-notes">${notes.map((n,i)=>`<button data-note="${i}" style="--note:${n.color};--angle:${n.angle}" aria-label="${n.name}의 포스트잇">${n.name}<small>작업 기록</small></button>`).join('')}</div>`;}
function renderView(){const w=$('workspace');if(view==='order'){
 $('view-title').textContent='멈춰 있는 작업 기록';w.innerHTML=`<p class="stamp">마지막 네 작업 · 인화가 끝난 순서</p><div class="bench"><div class="rail-label"><span>먼저</span><span>→</span><span>나중</span></div><div class="slots">${state.order.map((tag,i)=>`<div class="slot ${selectedSlot===i?'selected':''}" data-slot="${i}"><button class="plate" data-slot="${i}" aria-label="${i+1}번 칸 ${TAG_LABELS[tag]}판 선택" aria-pressed="${selectedSlot===i}"><span class="symbol">${TAG_LABELS[tag]}</span></button><span class="number">${i+1}</span></div>`).join('')}</div><div class="handle"></div></div><p class="caption">판 두 장을 차례로 누르면 서로 바뀌어요.<br>직접 끌어서 자리를 바꿀 수도 있어요.</p>${deskNotes()}`;foot('feed','캐리어 밀어 넣기');return;}
 if(view==='projector'){
 $('view-title').textContent='빛이 지나간 자리';w.innerHTML=`<div class="light-plates">${TAGS.map((tag,i)=>{const mask=state.faces[i]?flipMask(MASKS[tag]):MASKS[tag];return`<button class="mask-card ${i===0?'keyed':''}" data-flip="${i}" aria-label="${TAG_LABELS[tag]}판 ${i===0?'고정됨':state.faces[i]?'뒷면 · 앞면으로 뒤집기':'앞면 · 뒷면으로 뒤집기'}"><span class="mask-head"><b>${TAG_LABELS[tag]}</b><small>${i===0?'비대칭 고정 핀':state.faces[i]?'뒷면 ↻':'앞면 ↻'}</small></span><span class="mask-grid">${Array.from({length:16},(_,j)=>`<i class="${mask&(1<<j)?'open':''}"></i>`).join('')}</span></button>`;}).join('')}</div><div class="receiver" aria-label="빛 수신판">${receiverHTML()}</div><p class="caption">겹친 구멍이 한 점일 때, 보관함의 걸쇠가 풀려요.</p><div class="experiment-history">${state.experiments.slice(-3).map(e=>`<span>${e.faces.map(x=>x?'뒤':'앞').join('')} · ${e.lit.length}점</span>`).join('')}</div><button class="subtle" data-act="sample" style="display:block;margin:auto">작은 샘플판으로 시험하기</button>`;foot(state.archive?'archive':'project',state.archive?'C3 보관함 열어보기':'빛 비추기');return;}
 if(view==='archive'){
 ui.seen.ledger=true;save();$('view-title').textContent='열린 서랍 · C3';w.innerHTML=`<div class="folio"><h3>마지막 날의 배달 장부</h3><p>세 번째 작업</p><p style="font-size:23px">우편 발송</p><div class="seal-text">봉투를 인화가 끝난 순서대로 정리할 것.</div></div><div class="folio" style="transform:rotate(-1deg)"><h3>새 작업실 주소표</h3><p>하루의 사진은<br>새 작업실로 보내 주세요.</p><p style="text-align:right;font-size:12px">— 아버지</p></div><p class="dark-note">네 장은 서로 다른 사람의 사진이었어요.<br>벽의 메모 뒷면에도 수령 부탁이 남아 있었죠.</p>${deskNotes()}`;foot('delivery','네 장의 사진 정리하기');return;}
 if(view==='delivery'){
 $('view-title').textContent='아직 주인을 찾지 못한 사진들';const d=ui.draft;w.innerHTML=`<p class="stamp">이름표를 고르고, 사진의 빈칸에 놓아 주세요.</p><div class="photo-grid">${TAGS.map((tag,i)=>`<div class="photo-packet" style="--angle:${[-1,1,1,-1][i]}deg;--position:${['left top','right top','left bottom','right bottom'][i]}"><div class="photo-image"><span class="tag">${TAG_LABELS[tag]}</span></div><button class="attach ${d.people[i]?'filled':''}" data-attach="people:${i}" aria-label="${i+1}번 사진 이름표 ${d.people[i]?names[d.people[i]]:'빈칸'}">${d.people[i]?names[d.people[i]]:'이름표 놓기'}</button><button class="attach ${d.destinations[i]?'filled':''}" data-attach="destinations:${i}" aria-label="${i+1}번 사진 행선지 ${d.destinations[i]?places[d.destinations[i]]:'빈칸'}">${d.destinations[i]?places[d.destinations[i]]:'행선지 놓기'}</button></div>`).join('')}</div><p class="group-label">이름표 · 한 사람씩</p><div class="token-pool">${PEOPLE.map(p=>`<button class="token ${d.people.includes(p)?'used':''} ${selectedToken?.value===p?'chosen':''}" data-token="people:${p}" aria-pressed="${selectedToken?.value===p}">${names[p]}</button>`).join('')}</div><p class="group-label">행선지 · 한 곳씩</p><div class="token-pool">${DESTINATIONS.map(p=>`<button class="token ${d.destinations.includes(p)?'used':''} ${selectedToken?.value===p?'chosen':''}" data-token="destinations:${p}" aria-pressed="${selectedToken?.value===p}">${places[p]}</button>`).join('')}</div><button class="subtle" data-act="ledger" style="display:block;margin:auto">배달 장부 다시 보기</button>`;foot('deliver','봉투에 담아 돌려보내기');return;}
}
function receiverHTML(){const lit=showLight?cells(project(state.faces)).map(c=>c.address):[];let html='<span></span>'+[1,2,3,4].map(i=>`<span class="axis">${i}</span>`).join('');for(let r=0;r<4;r++){html+=`<span class="axis">${'ABCD'[r]}</span>`;for(let c=0;c<4;c++){const id='ABCD'[r]+(c+1);html+=`<span class="lamp ${lit.includes(id)?'lit':''}" aria-label="${id} ${lit.includes(id)?'켜짐':'꺼짐'}">${lit.includes(id)?id:''}</span>`;}}return html;}
function sample(){sampleTurned=false;showPaper('sample',`<p class="overline">작은 샘플 · 겹치는 곳만 빛이 통과한다</p><h2>빛은 두 판을<br>모두 지나야 해요.</h2><div class="sample"><div class="mask-grid"><i class="open"></i><i></i><i></i><i class="open"></i></div><span>∩</span><div class="mask-grid"><i></i><i class="open"></i><i class="open"></i><i></i></div></div><p class="small" id="sample-result">지금은 구멍이 하나도 겹치지 않아요.</p><button class="action" data-act="sample-flip">두 번째 샘플판 뒤집기</button><button class="subtle" data-act="close-paper">실제 판으로 돌아가기</button>`);}
function place(kind,i){if(!selectedToken){message('아래에서 이름표나 행선지표를 먼저 골라 주세요.');return;}if(selectedToken.kind!==kind){message(kind==='people'?'이 칸에는 이름표를 놓아요.':'이 칸에는 행선지표를 놓아요.');return;}const values=[...ui.draft[kind]],other=values.indexOf(selectedToken.value),old=values[i];if(other>=0)values[other]=old;values[i]=selectedToken.value;ui.draft[kind]=values;selectedToken=null;save();tick();renderView();}
function ledger(){showPaper('ledger',`<p class="overline">C3 · 배달 장부</p><h2>지워지지 않은 두 줄</h2><p>세 번째 작업은 우편 발송.\n\n하루의 사진은 새 작업실로.</p><p class="small">인화가 끝난 순서대로 정리할 것.</p><button class="subtle" data-act="close-paper">배달대로 돌아가기</button>`);}
function ending(){showPaper('ending',`<p class="overline">마지막 현상실 · 기록 복원 완료</p><h2>가게는 문을 닫아도,<br>사진은 도착한다.</h2><div class="result-photos">${TAGS.map((t,i)=>`<div style="--angle:${i%2?2:-2}deg;--position:${['left top','right top','left bottom','right bottom'][i]}"><div class="photo-image"></div>${names[PEOPLE[i]]} · ${places[DESTINATIONS[i]]}</div>`).join('')}</div><p>“네 장 모두 잘 도착했어요.\n아버지는 새 작업실에서\n다시 인화를 시작하셨어요.”</p><p class="signature">— 하루의 답장</p><button class="action" data-act="return-room">불 꺼지기 전, 잠시 머물기</button><p class="small">첫 사건은 여기까지예요.\n이어서 풀 두 번째 사건은 아직 준비 중이에요.</p>`);}
function menu(){showPaper('menu',`<p class="overline">AFTERLIGHT · 0.20.3</p><h2>마지막 현상실</h2><p class="small">진행은 이 기기에 자동 저장돼요.\n${storage?'다른 여행 이야기의 저장 기록도 그대로예요.':'이 브라우저에서는 저장이 제한되고 있어요.'}</p><button class="action secondary" data-act="sound">효과음 ${ui.sound?'끄기':'켜기'}</button><button class="action secondary" data-act="restart-question">이 사건 처음부터</button><button class="subtle" data-act="close-paper">방으로 돌아가기</button><a class="subtle" href="../index.html?chapter=tokyo" style="display:block;text-align:center">이전 여행 이야기</a>`);}
function hint(){const phase=state.complete?'complete':state.phase;if(hintPhase!==phase){hintLevel=0;hintPhase=phase;}const h={table:['세 사람은 같은 인화 작업의 서로 다른 순간을 기억해요.','바로 다음, 사이 한 작업, 먼저. 이 세 관계를 한 줄에 놓아 보세요.','△와 ○를 붙이고, ○보다 두 칸 뒤에 +가 오도록 놓아 보세요.'],projector:['한 판의 구멍이 아니라, 네 판을 모두 통과하는 빛을 찾아요.','고정된 △를 기준으로, 다른 판을 뒤집기 전후의 구멍을 비교해 보세요.','○와 +를 뒷면으로, □는 앞면으로 놓아 시험해 보세요.'],archive:['사진의 주인과 행선지를 따로 생각한 뒤 연결해 보세요.','포스트잇 뒷면의 부탁과 C3 장부를 함께 읽어요.','우편을 세 번째에 놓고 유이 다음 켄, 하루=작업실, 켄=보관함을 연결해 보세요.'],complete:['네 장의 사진이 모두 제자리를 찾았어요.','관찰 수첩에서 지나온 실험을 볼 수 있어요.','작업대의 새 봉투를 열면 답장을 다시 볼 수 있어요.']};showPaper('hint',`<p class="overline">요청한 도움 · ${hintLevel+1} / 3</p><h2>조금만 다른 각도에서</h2><p>${h[phase][hintLevel]}</p><button class="subtle" data-act="more-hint">${hintLevel<2?'조금 더 구체적으로':'처음 힌트부터'}</button><button class="subtle" data-act="close-paper">직접 해볼게요</button>`);}
function chooseSlot(i){if(selectedSlot===null){selectedSlot=i;renderView();return;}const o=[...state.order];[o[selectedSlot],o[i]]=[o[i],o[selectedSlot]];selectedSlot=null;action({type:'arrange',order:o});renderView();}
function handle(actName){switch(actName){case'request':request();break;case'begin':ui.started=true;save();closePaper();renderRoom();say('벽에 남은 세 사람의 기록.\n작업대의 네 판과 연결돼 있을까요?',6500);break;case'close-paper':closePaper();break;case'order':openView('order');break;case'projector':openView('projector');break;case'archive':openView('archive');break;case'delivery':openView('delivery');break;case'flip-note':openNote(noteIndex,1-noteSide);break;case'feed':{const r=action({type:'feed'});if(r.ok){showLight=false;openView('projector');message('걸쇠가 풀렸어요.\n이 판들은 빛을 통과시키는 기록이었네요.');flash();}break;}case'project':{showLight=true;const r=action({type:'project'});if(r.ok){renderView();message(r.state.archive?'한 줄기의 빛이 C3에 닿았어요.\n오른쪽 보관함에서 걸쇠 소리가 나요.':r.observation.lit.length?'빛이 여러 곳으로 갈라져요.\n판을 뒤집어 통로를 비교해 볼까요?':'네 판을 모두 통과하는 구멍이 없어요.');if(r.state.archive){tick('open');flash();}}break;}case'sample':sample();break;case'sample-flip':{sampleTurned=!sampleTurned;const b=$('paper').querySelectorAll('.sample .mask-grid')[1];b.innerHTML=sampleTurned?'<i class="open"></i><i></i><i></i><i class="open"></i>':'<i></i><i class="open"></i><i class="open"></i><i></i>';$('sample-result').textContent=sampleTurned?'두 구멍이 겹쳤어요. 실제 장치는 한 점만 남겨야 해요.':'지금은 구멍이 하나도 겹치지 않아요.';break;}case'ledger':ledger();break;case'deliver':{const d=ui.draft;if(d.people.some(x=>!x)||d.destinations.some(x=>!x)){message('사진마다 이름표와 행선지표가 한 장씩 필요해요.');break;}if(action({type:'assign',people:d.people,destinations:d.destinations}).ok&&action({type:'deliver'}).ok){closeView();flash();ending();}break;}case'ending':ending();break;case'return-room':closePaper();closeView();say('새 작업실의 불은 아직 켜져 있을 거예요.');break;case'more-hint':hintLevel=(hintLevel+1)%3;hint();break;case'sound':ui.sound=!ui.sound;save();tick('open');menu();break;case'restart-question':showPaper('restart',`<h2>이 사건을 다시 시작할까요?</h2><p>마지막 현상실의 진행만 지워져요.\n이전 여행 이야기의 기록은 남아요.</p><button class="action" data-act="restart">이 사건 다시 시작</button><button class="subtle" data-act="close-paper">계속 이어하기</button>`);break;case'restart':log=[];state=initial();ui={started:false,seen:{},draft:blankDraft(),sound:ui.sound};save();closePaper();closeView();selectedToken=null;showLight=false;renderRoom();break;}}
function flash(){const f=document.createElement('div');f.className='flash';app.append(f);setTimeout(()=>f.remove(),700);}
app.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||!ready)return;if(el.dataset.note!==undefined){openNote(Number(el.dataset.note));return;}if(el.dataset.slot!==undefined&&view==='order'){if(pointer?.suppress)return;chooseSlot(Number(el.dataset.slot));return;}if(el.dataset.flip!==undefined){const r=action({type:'flip',index:Number(el.dataset.flip)});if(r.ok){showLight=false;renderView();}return;}if(el.dataset.token){const[k,v]=el.dataset.token.split(':');selectedToken={kind:k,value:v};renderView();return;}if(el.dataset.attach){const[k,i]=el.dataset.attach.split(':');place(k,Number(i));return;}if(el.dataset.act)handle(el.dataset.act);});
$('workspace').addEventListener('pointerdown',e=>{const plate=e.target.closest('.plate');if(!plate||view!=='order'||e.button!==0)return;pointer={id:e.pointerId,index:Number(plate.dataset.slot),x:e.clientX,y:e.clientY,moved:false,suppress:false};plate.setPointerCapture(e.pointerId);});
$('workspace').addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;if(Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>10){pointer.moved=true;e.target.closest('.plate')?.classList.add('dragging');}});
$('workspace').addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;if(!p.moved)return;const nodes=[...$('workspace').querySelectorAll('.slot')];const target=nodes.find(n=>{const r=n.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;});if(target){const o=[...state.order],to=Number(target.dataset.slot);[o[p.index],o[to]]=[o[to],o[p.index]];action({type:'arrange',order:o});}selectedSlot=null;renderView();pointer={suppress:true};setTimeout(()=>{pointer=null;},100);});
$('workspace').addEventListener('pointercancel',()=>{pointer=null;renderView();});
$('menu').onclick=()=>{if(ready)menu();};$('hint').onclick=()=>{if(ready)hint();};$('request').onclick=()=>{if(ready)request();};$('notebook').onclick=()=>{if(ready)notebook();};$('view-notes').onclick=()=>notebook();$('view-help').onclick=()=>hint();$('view-back').onclick=closeView;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('modal').hidden&&ui.started)closePaper();else if(view)closeView();return;}if(e.key==='Tab'&&!$('modal').hidden){const f=[...$('paper').querySelectorAll('button,a[href]')].filter(n=>!n.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
renderRoom();try{const img=new Image();img.src='room.webp';await img.decode();ready=true;$('loading').hidden=true;if(!ui.started)say('작업대 위, 아직 열지 않은 봉투가 있어요.',7000);else if(state.complete)say('네 장의 사진을 모두 돌려보냈어요.');else if(state.archive)say('열린 C3 보관함에 마지막 배달 기록이 남아 있어요.');}catch{$('loading').innerHTML='<button class="action" id="reload">불러오지 못했어요 · 다시 열기</button>';$('reload').onclick=()=>location.reload();}
